// News cards and published utilization articles are the editorial sources.
// Run through npm run build; do not edit js/pages/content-index.js by hand.
// Edit news card titles, dates, badges and SDG links/data-sdgs in news-events.html.
// Edit published project metadata in OFFICIAL_UTILIZATION_ARTICLES in utilization.js.
// NewsArticle headlines follow news titles automatically. build-social.js then
// generates share pages/images from NewsArticle data and published utilization data.
// Publication timestamps are intentionally never replaced by build/edit dates.
// Social regression checks: node tools/test-social.js.
// legacy-sdg-listings.json preserves an older entry with no matching source card:
// replace its fallback URL only after its dedicated story has been verified.
// Regression checks: node tools/test-content.js and node tools/test-responsive.js.
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const root = path.resolve(__dirname, '..');
const read = file => fs.readFileSync(path.join(root, file), 'utf8');
const write = (file, text) => {
  if (!fs.existsSync(path.join(root, file)) || read(file) !== text) fs.writeFileSync(path.join(root, file), text);
};
const text = html => html.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
const field = (html, name) => {
  const match = html.match(new RegExp('<[\\w]+\\b[^>]*class="[^"]*\\b' + name + '\\b[^"]*"[^>]*>([\\s\\S]*?)<\\/[^>]+>'));
  return match ? text(match[1]) : '';
};
function newsRecords(html) {
  return [...html.matchAll(/<article\b([^>]*)>([\s\S]*?)<\/article>/g)].filter(m => /\bnews-card\b/.test(m[1])).map(([, attrs, body]) => {
    const id = (attrs.match(/\bid="([^"]+)"/) || [])[1];
    if (!id) throw new Error('News card requires a stable id');
    const goals = [...(attrs.match(/data-sdgs="([^"]*)"/) || ['', ''])[1].split(/\s+/).map(Number), ...[...body.matchAll(/sdg-overview\.html\?goal=(\d+)/g)].map(m => Number(m[1]))].filter(n => n >= 1 && n <= 17);
    const date = field(body, 'news-date-badge') || field(body, 'article-meta-date');
    return { id, t: field(body, 'news-title') || field(body, 'article-accordion-title'), r: date, d: '—', m: date, topic: field(body, 'badge-editorial-topic') || field(body, 'dropdown-badge'), g: [...new Set(goals)].sort((a,b) => a-b), url: 'news-events.html#' + id };
  });
}
function projectRecords(source) {
  const literal = source.match(/var OFFICIAL_UTILIZATION_ARTICLES = (\[[\s\S]*?\n    \]);/);
  if (!literal) throw new Error('Published utilization data not found');
  return vm.runInNewContext('(' + literal[1] + ')', {}, { timeout: 1000 }).filter(a => a.isPublished).map(a => ({ id: a.id, t: a.title, r: a.date, d: '—', m: 'Research utilization', topic: a.topic, g: a.sdgs.map(s => Number(s.goal)), url: 'utilization.html#' + a.id }));
}
function updateAdvocacyCounts(records) {
  const file = 'adg-advocacy.html';
  const counts = Array.from({ length: 17 }, (_, i) => records.filter(r => r.g.includes(i + 1)).length);
  let html = read(file).replace(/<a href="sdg-overview\.html\?goal=(\d+)" class="sdg-pure-card"[^>]*>([\s\S]*?)<\/a>/g, (all, goal, body) => {
    const count = counts[Number(goal) - 1];
    const name = (body.match(/<img[^>]*alt="([^"]+)"/) || [])[1];
    if (!name) throw new Error('SDG card requires a goal name');
    const label = count === 1 ? '1 documented item' : count + ' documented items';
    const badgeClass = count === 0 ? 'zero' : count >= 15 ? 'highlight' : 'has-events';
    const badgeText = count === 0 ? 'No items yet' : count + (count === 1 ? ' Item' : ' Items');
    body = body.replace(/<span class="sdg-count-badge[\s\S]*?<\/span>[^<]*<\/span>/, '<span class="sdg-count-badge ' + badgeClass + '" aria-hidden="true"><span class="badge-dot"></span>' + badgeText + '</span>');
    return '<a href="sdg-overview.html?goal=' + goal + '" class="sdg-pure-card" title="' + name + ' (' + label + ')" aria-label="' + name + ', ' + label + '">' + body + '</a>';
  });
  const coveredGoals = counts.filter(count => count > 0).length;
  html = html.replace('<!-- Update this total whenever the badge counts above change -->', '<!-- Counts generated by tools/build-content.js from the shared content index. -->');
  html = html.replace(/<p class="sdg-total-note">[\s\S]*?<\/p>/, '<p class="sdg-total-note"><strong>' + records.length + ' distinct documented items</strong> across ' + coveredGoals + ' of the 17 goals. Items include news stories, events, projects, and initiatives. One activity may support multiple SDGs and appear under more than one goal; goal counts should not be added together to calculate a total.</p>');
  write(file, html);
}
function buildContent() {
  let newsHtml = read('news-events.html');
  const news = newsRecords(newsHtml);
  newsHtml = newsHtml.replace(/(<script type="application\/ld\+json">)([\s\S]*?)(<\/script>)/g, (all, start, json, end) => {
    const data = JSON.parse(json);
    for (const article of data['@graph'] || []) {
      if (article['@type'] !== 'NewsArticle' || !article.mainEntityOfPage) continue;
      const id = new URL(article.mainEntityOfPage).searchParams.get('article');
      const record = news.find(r => r.id === id);
      if (record) article.headline = record.t;
    }
    if (JSON.stringify(data) === JSON.stringify(JSON.parse(json))) return all;
    return start + '\n  ' + JSON.stringify(data, null, 2).replace(/\n/g, '\n  ') + '\n  ' + end;
  });
  write('news-events.html', newsHtml);
  const projects = projectRecords(read('js/pages/utilization.js'));
  const records = [...news, ...projects, ...JSON.parse(read('tools/legacy-sdg-listings.json'))];
  if (new Set(records.map(r => r.id)).size !== records.length) throw new Error('Duplicate content ids');
  if (records.some(r => !r.t || !r.g.every(n => n >= 1 && n <= 17))) throw new Error('Invalid content metadata');
  write('js/pages/content-index.js', '// Generated by tools/build-content.js from news and utilization sources.\nwindow.RDC_CONTENT = ' + JSON.stringify(records, null, 2) + ';\n');
  updateAdvocacyCounts(records);
  // Share previews use the news title; their existing description remains the
  // single description source for Open Graph, Twitter and the fallback text.
  news.filter(r => r.id.startsWith('article-')).forEach(r => {
    const file = 'share/' + r.id + '.html';
    if (!fs.existsSync(path.join(root, file))) return;
    let html = read(file);
    const description = (html.match(/<meta name="description" content="([^"]*)"/) || [])[1];
    const escape = s => s.replace(/"/g, '&quot;');
    html = html.replace(/<title>[\s\S]*?<\/title>/, '<title>' + r.t + ' | MCNP &amp; ISAP RDC</title>')
      .replace(/(<meta (?:property="og:title"|name="twitter:title") content=")[^"]*(")/g, '$1' + escape(r.t) + '$2')
      .replace(/<h1>[\s\S]*?<\/h1>/, '<h1>' + r.t + '</h1>');
    if (description) html = html.replace(/(<meta (?:property="og:description"|name="twitter:description") content=")[^"]*(")/g, '$1' + description + '$2');
    write(file, html);
  });
  console.log(`Indexed ${news.length} news items and ${projects.length} published utilization articles.`);
  return records;
}
module.exports = { buildContent, newsRecords, projectRecords };
if (require.main === module) buildContent();
